int main()
{
	int n;
	cout << "Enter a number to find the nth fibonacci number: ";
	cin >> n;

	int *arr = new int[n + 1];
	arr[0] = 0;
	arr[1] = 1;
	for (int i = 2; i <= n; i++)
	{
		arr[i] = arr[i - 1] + arr[i - 2];
	}
	cout << "The nth fibonacci number is: " << arr[n];
	delete[] arr;
	return 0;
}
